import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;public class TestClass {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String s = br.readLine();if (s == null || s.isEmpty()) return;int n = s.length();int[] results = new int[n];int count = 0;for (int i = n - 1; i >= 0; i--) {int digit = s.charAt(i) - '0';if (digit % 2 == 0) {count++;}results[i] = count;}StringBuilder sb = new StringBuilder();for (int i = 0; i < n; i++) {sb.append(results[i]);if (i < n - 1) {sb.append(" ");}}System.out.println(sb.toString());}}